// 三个入口同一形状门；逐层拒重名、未知枚举、失真Owner/预约与无变化的伪差量。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "growth_market_history_codec.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include "resident/storage/common_projection.hpp"
#include <algorithm>
#include <initializer_list>
#include <charconv>
#include <set>
namespace hanmo::resident {namespace {
using V=BoundaryValue;
bool reference(const StableId& s){return !s.empty()&&s.size()<=256;}
bool canonical(const StableId& s,const StableId& prefix){if(s.rfind(prefix+":",0)!=0)return false;auto digits=s.substr(prefix.size()+1);Integer n=0;auto r=std::from_chars(digits.data(),digits.data()+digits.size(),n);return r.ec==std::errc{}&&r.ptr==digits.data()+digits.size()&&n>0&&std::to_string(n)==digits;}
bool ordered(const FieldOrder& f,std::initializer_list<const char*> keys){if(f.empty())return true;if(f.size()!=keys.size())return false;for(std::size_t i=0;i<f.size();++i){if(std::none_of(keys.begin(),keys.end(),[&](const char* key){return f[i]==key;})||std::find(f.begin(),f.begin()+static_cast<std::ptrdiff_t>(i),f[i])!=f.begin()+static_cast<std::ptrdiff_t>(i))return false;}return true;}
// BoundaryValue也能由C++调用者直接提供，因此不能只依赖文本JSON parser的拒重名。
void unique(const V& v,Integer depth=0){if(depth>64)boundary::fail("GrowthMarketBoundaryTooDeep","");if(const auto* object=v.as<V::Dict>()){std::set<StableId> keys;for(const auto& row:*object){if(!keys.insert(row.first).second)boundary::fail("DuplicateGrowthMarketField",row.first);unique(row.second,depth+1);}}else if(const auto* array=v.as<V::Array>())for(const auto& item:*array)unique(item,depth+1);}
Status lot_shape(const LotView& lot){const auto kind=static_cast<Integer>(lot.owner.kind);return canonical(lot.id,"lot")&&reference(lot.item_id)&&lot.quantity>0&&!lot.extra&&!lot.owner.extra&&reference(lot.owner.id)&&kind>=0&&kind<=3&&lot.reserved_by.kind==ReservationRef::Kind::action&&lot.reserved_by.id.empty()&&ordered(lot.field_order,{"id","item_id","quantity","owner","reserved_by"})&&ordered(lot.owner.field_order,{"kind","id"})?common_success():common_failure("InvalidGrowthMarketLot",lot.id);}
Status shape(const MarketLotChange& v){if(!canonical(v.lot_id,"lot")||(!v.before&&!v.after)||!ordered(v.field_order,{"lot_id","before","after"}))return common_failure("InvalidGrowthMarketLotChange",v.lot_id);for(const auto* p:{&v.before,&v.after})if(*p){auto valid=lot_shape(**p);if(!valid.ok)return valid;if((*p)->id!=v.lot_id)return common_failure("InvalidGrowthMarketLotChange",v.lot_id);}if(v.before&&v.after&&(v.before->item_id!=v.after->item_id||!owner_equal(v.before->owner,v.after->owner)||v.after->quantity>=v.before->quantity))return common_failure("InvalidGrowthMarketLotChange",v.lot_id);return common_success();}
Status shape(const MarketInventoryChange& v){if(!reference(v.inventory_id)||v.revision_before<0||v.revision_after<=v.revision_before||v.lots.empty()||v.lots.size()>1000000||!ordered(v.field_order,{"inventory_id","revision_before","revision_after","lots"}))return common_failure("InvalidGrowthMarketInventoryChange",v.inventory_id);for(std::size_t i=0;i<v.lots.size();++i){const auto& p=v.lots[i];if(std::any_of(v.lots.begin(),v.lots.begin()+static_cast<std::ptrdiff_t>(i),[&](const auto& prior){return prior.lot_id==p.lot_id;}))return common_failure("DuplicateGrowthMarketLotChange",p.lot_id);auto valid=shape(p);if(!valid.ok)return valid;}return common_success();}
Status shape(const MarketCaptureStep& v){const auto stage=static_cast<Integer>(v.stage);if(!std::holds_alternative<MarketLegacyOriginalStep>(v.source_binding)||stage<0||stage>3||v.next_instance_before<1||v.next_instance_after<v.next_instance_before||v.inventories.empty()||v.inventories.size()>4096||!ordered(v.field_order,{"stage","next_instance_before","next_instance_after","inventories"}))return common_failure("InvalidGrowthMarketCaptureStep");for(std::size_t i=0;i<v.inventories.size();++i){const auto& p=v.inventories[i];if(std::any_of(v.inventories.begin(),v.inventories.begin()+static_cast<std::ptrdiff_t>(i),[&](const auto& prior){return prior.inventory_id==p.inventory_id;}))return common_failure("DuplicateGrowthMarketCaptureInventory",p.inventory_id);auto valid=shape(p);if(!valid.ok)return valid;}return common_success();}
Status shape(const MarketMovementRecord& v){const auto kind=static_cast<Integer>(v.business_kind);if(v.business_source_schema!=1||v.original_business_execution||v.kind!="growth_market_movement"||!reference(v.business_fact_id)||kind<0||kind>2||v.source_tick<0||v.observed_tick<0||v.steps.empty()||v.steps.size()>2||!ordered(v.field_order,{"kind","business_fact_id","business_kind","source_tick","observed_tick","steps"}))return common_failure("InvalidGrowthMarketMovement");Integer previous=-1;for(const auto& p:v.steps){auto valid=shape(p);if(!valid.ok)return valid;auto stage=static_cast<Integer>(p.stage);if(stage<=previous||(kind==0&&stage!=0)||(kind==1&&(stage<1||stage>2))||(kind==2&&stage!=3))return common_failure("InvalidGrowthMarketCaptureStage");previous=stage;}return common_success();}
// 缺预约是该显式profile的固定合同，仍写其typed空值以保Lot原字段语义。
Status emit_lot_fields(ProjectionWriter& w,const LotView& p){w.field("id",p.id);w.field("item_id",p.item_id);w.field("quantity",p.quantity);emit_common_owner(w,"owner",p.owner);emit_common_reservation(w,"reserved_by",p.reserved_by,true,false);return w.order_fields(p.field_order);}
LotView read_lot(const V& v){using namespace boundary;fields(v,{"id","item_id","quantity","owner","reserved_by"},{},"market/lot");const auto& reservation=field(v,"reserved_by","");fields(reservation,{"kind","id"},{},"market/lot/reserved_by");if(order(reservation)!=FieldOrder{"kind","id"})fail("InvalidGrowthMarketReservationOrder","");LotView out{get_string(v,"id",""),get_string(v,"item_id",""),decode_reservation_ref(reservation,""),get_int(v,"quantity",""),decode_owner(field(v,"owner",""),""),{},order(v)};auto valid=lot_shape(out);if(!valid.ok)fail(valid.error.original.code,valid.error.original.path);return out;}
Status emit_fields(ProjectionWriter& w,const MarketLotChange& p){w.field("lot_id",p.lot_id);w.optional("before",p.before,emit_lot_fields);w.optional("after",p.after,emit_lot_fields);return w.order_fields(p.field_order);}
MarketLotChange read_change(const V& v){using namespace boundary;fields(v,{"lot_id","before","after"},{},"market/change");MarketLotChange p;p.lot_id=get_string(v,"lot_id","");const auto& before=field(v,"before","");const auto& after=field(v,"after","");if(!before.as<std::monostate>())p.before=read_lot(before);if(!after.as<std::monostate>())p.after=read_lot(after);p.field_order=order(v);return p;}
Status emit_fields(ProjectionWriter& w,const MarketInventoryChange& p){w.field("inventory_id",p.inventory_id);w.field("revision_before",p.revision_before);w.field("revision_after",p.revision_after);w.sequence("lots",p.lots,[](auto& out,const auto& row){return out.object("",[&](auto& fields){return emit_fields(fields,row);});});return w.order_fields(p.field_order);}
MarketInventoryChange read_inventory(const V& v){using namespace boundary;fields(v,{"inventory_id","revision_before","revision_after","lots"},{},"market/inventory");MarketInventoryChange p;p.inventory_id=get_string(v,"inventory_id","");p.revision_before=get_int(v,"revision_before","");p.revision_after=get_int(v,"revision_after","");for(const auto& lot:array(field(v,"lots",""),"lots"))p.lots.push_back(read_change(lot));p.field_order=order(v);return p;}
Status emit_fields(ProjectionWriter& w,const MarketCaptureStep& p){w.field("stage",static_cast<Integer>(p.stage));w.field("next_instance_before",p.next_instance_before);w.field("next_instance_after",p.next_instance_after);w.sequence("inventories",p.inventories,[](auto& out,const auto& row){return out.object("",[&](auto& fields){return emit_fields(fields,row);});});return w.order_fields(p.field_order);}
MarketCaptureStep read_step(const V& v){using namespace boundary;fields(v,{"stage","next_instance_before","next_instance_after","inventories"},{},"market/step");MarketCaptureStep p;const auto stage=get_int(v,"stage","");if(stage<0||stage>3)fail("InvalidGrowthMarketCaptureStage","");p.stage=static_cast<MarketCaptureStage>(stage);p.next_instance_before=get_int(v,"next_instance_before","");p.next_instance_after=get_int(v,"next_instance_after","");for(const auto& row:array(field(v,"inventories",""),"inventories"))p.inventories.push_back(read_inventory(row));p.field_order=order(v);return p;}
Status emit_fields(ProjectionWriter& w,const MarketMovementRecord& p){w.field("kind",p.kind);w.field("business_fact_id",p.business_fact_id);w.field("business_kind",static_cast<Integer>(p.business_kind));w.field("source_tick",p.source_tick);w.field("observed_tick",p.observed_tick);w.sequence("steps",p.steps,[](auto& out,const auto& row){return out.object("",[&](auto& fields){return emit_fields(fields,row);});});return w.order_fields(p.field_order);}
MarketMovementRecord read_record(const V& v){using namespace boundary;fields(v,{"kind","business_fact_id","business_kind","source_tick","observed_tick","steps"},{},"market/movement");MarketMovementRecord p;p.kind=get_string(v,"kind","");p.business_fact_id=get_string(v,"business_fact_id","");auto kind=get_int(v,"business_kind","");if(kind<0||kind>2)fail("InvalidGrowthMarketBusinessKind","");p.business_kind=static_cast<MarketCauseKind>(kind);p.source_tick=get_int(v,"source_tick","");p.observed_tick=get_int(v,"observed_tick","");for(const auto& row:array(field(v,"steps",""),"steps"))p.steps.push_back(read_step(row));p.field_order=order(v);return p;}
// 独立v1段的Owner始终支持原四种typed权属，不由其他旧域的feature位决定新段字节。
Status visit_lot(CodecVisitor& c,LotView& p){c.field("id",p.id);c.field("item_id",p.item_id);c.field("quantity",p.quantity);c.object("owner",[&](CodecVisitor& q){auto flags=q.schema_features;q.schema_features|=common_checkpoint::typed_resource_references;auto r=common_checkpoint::owner(q,p.owner);q.schema_features=flags;return r;});c.object("reserved_by",[&](CodecVisitor& q){Integer kind=static_cast<Integer>(p.reserved_by.kind);q.field("kind",kind);q.field("id",p.reserved_by.id);if(kind!=0||!p.reserved_by.id.empty())return q.reject("InvalidGrowthMarketReservation");if(q.reading())p.reserved_by.kind=ReservationRef::Kind::action;return q.status();});common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=lot_shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
Status visit(CodecVisitor& c,MarketLotChange& p){c.field("lot_id",p.lot_id);c.optional("before",p.before,visit_lot);c.optional("after",p.after,visit_lot);common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
Status visit(CodecVisitor& c,MarketInventoryChange& p){c.field("inventory_id",p.inventory_id);c.field("revision_before",p.revision_before);c.field("revision_after",p.revision_after);c.sequence("lots",p.lots,[](CodecVisitor& q,MarketLotChange& v){return visit(q,v);});common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
Status visit(CodecVisitor& c,MarketCaptureStep& p){Integer stage=static_cast<Integer>(p.stage);c.field("stage",stage);if(stage<0||stage>3)return c.reject("InvalidGrowthMarketCaptureStage");if(c.reading())p.stage=static_cast<MarketCaptureStage>(stage);c.field("next_instance_before",p.next_instance_before);c.field("next_instance_after",p.next_instance_after);c.sequence("inventories",p.inventories,[](CodecVisitor& q,MarketInventoryChange& v){return visit(q,v);});common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
Status visit(CodecVisitor& c,MarketMovementRecord& p){c.field("kind",p.kind);c.field("business_fact_id",p.business_fact_id);Integer kind=static_cast<Integer>(p.business_kind);c.field("business_kind",kind);if(kind<0||kind>2)return c.reject("InvalidGrowthMarketBusinessKind");if(c.reading())p.business_kind=static_cast<MarketCauseKind>(kind);c.field("source_tick",p.source_tick);c.field("observed_tick",p.observed_tick);c.sequence("steps",p.steps,[](CodecVisitor& q,MarketCaptureStep& v){return visit(q,v);});common_checkpoint::strings(c,"field_order",p.field_order);if(!c.status().ok)return c.status();auto valid=shape(p);return valid.ok?c.status():c.reject(valid.error.original.code);}
}
Status validate_growth_market_history_shape(const GrowthMarketHistoryState& s){if(s.version!=1||!ordered(s.field_order,{"version","movements"})||s.movements.size()>1000000)return common_failure("InvalidGrowthMarketState");for(const auto& row:s.movements.rows()){if(!canonical(row.first,"market_history"))return common_failure("InvalidGrowthMarketMovementId",row.first);auto valid=shape(row.second);if(!valid.ok)return valid;}return common_success();}
Outcome<GrowthMarketHistoryState> decode_growth_market_history(const V& v){try{using namespace boundary;unique(v);fields(v,{"version","movements"},{},"growth_market_history");if(get_int(v,"version","")!=1)fail("UnsupportedGrowthMarketHistoryVersion","");GrowthMarketHistoryState out;for(const auto& row:object(field(v,"movements",""),"movements"))if(!out.movements.insert(row.first,read_record(row.second)))fail("DuplicateGrowthMarketMovement",row.first);out.field_order=order(v);auto valid=validate_growth_market_history_shape(out);if(!valid.ok)return {false,{},valid.error};return {true,std::move(out),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status emit_growth_market_history_fields(ProjectionWriter& w,const GrowthMarketHistoryState& s){auto valid=validate_growth_market_history_shape(s);if(!valid.ok)return valid;w.field("version",Integer{1});w.keyed_dictionary("movements",{},[&](auto& out){for(const auto& row:s.movements.rows())out.object(row.first,[&](auto& fields){return emit_fields(fields,row.second);});return out.status();});return w.order_fields(s.field_order);}
BoundaryValue encode_growth_market_history(const GrowthMarketHistoryState& s){BoundaryValue out;BoundaryProjectionWriter writer(out);auto valid=writer.object("",[&](auto& fields){return emit_growth_market_history_fields(fields,s);});if(valid.ok)valid=writer.finish();if(!valid.ok){boundary::DecodeFailure failure(valid.error.original.code,valid.error.original.path);failure.error=valid.error;throw failure;}return out;}
Status visit_growth_market_history_checkpoint(CodecVisitor& c,GrowthMarketHistoryState& s){Integer version=s.version;c.field("version",version);if(version!=1)return c.reject("UnsupportedGrowthMarketHistoryVersion");if(c.reading())s.version=version;common_checkpoint::table(c,"movements",s.movements,[](CodecVisitor& q,MarketMovementRecord& v){return visit(q,v);});common_checkpoint::strings(c,"field_order",s.field_order);if(!c.status().ok)return c.status();auto valid=validate_growth_market_history_shape(s);return valid.ok?c.status():c.reject(valid.error.original.code);}
}
